// @ts-ignore - pure JS model generated by m2cgen
import { score } from './churnModel.js';

export interface PlayerFeatures {
  total_sessions: number;
  avg_session_minutes: number;
  max_level: number;
  level_velocity: number;
  has_guild: number; // 0 or 1
  days_active_span: number;
  recency_days: number;
}

export interface PredictionResult {
  retainedProbability: number;
  churnProbability: number;
  riskLevel: 'Bajo' | 'Medio' | 'Alto';
  riskColor: string;
  recommendations: string[];
}

export const FEATURE_ORDER: (keyof PlayerFeatures)[] = [
  'total_sessions',
  'avg_session_minutes',
  'max_level',
  'level_velocity',
  'has_guild',
  'days_active_span',
  'recency_days'
];

export function predictChurn(features: PlayerFeatures): PredictionResult {
  const inputArray = [
    features.total_sessions,
    features.avg_session_minutes,
    features.max_level,
    features.level_velocity,
    features.has_guild,
    features.days_active_span,
    features.recency_days
  ];

  const rawOutput = score(inputArray) as [number, number];
  const retainedProbability = Math.max(0, Math.min(1, rawOutput[0]));
  const churnProbability = Math.max(0, Math.min(1, rawOutput[1]));

  let riskLevel: 'Bajo' | 'Medio' | 'Alto' = 'Bajo';
  let riskColor = '#10b981'; // green

  if (churnProbability >= 0.70) {
    riskLevel = 'Alto';
    riskColor = '#ef4444'; // red
  } else if (churnProbability >= 0.35) {
    riskLevel = 'Medio';
    riskColor = '#f59e0b'; // amber
  }

  // Generate actionable recommendations based on active variables
  const recommendations: string[] = [];

  if (features.recency_days > 14) {
    recommendations.push(
      `Alerta de inactividad: Lleva ${Math.round(features.recency_days)} días sin conectar. Activar campaña de reenganche (email de bienvenida/bonus de EXP).`
    );
  }

  if (features.has_guild === 0) {
    recommendations.push(
      'Jugador sin gremio: La falta de vínculo social incrementa el abandono un 27%. Sugerir hermandades activas recomendadas para su clase.'
    );
  }

  if (features.max_level < 60) {
    recommendations.push(
      `Fase de leveo vulnerable (Nivel ${features.max_level}): Ofrecer guías de mazmorras o eventos de doble experiencia para superar el valle de abandono.`
    );
  } else if (features.max_level >= 70 && features.max_level < 80) {
    recommendations.push(
      'Transición a Wrath of the Lich King: Brindar acceso directo a misiones en Rasganorte y equipamiento inicial de mazmorras.'
    );
  }

  if (features.avg_session_minutes < 25) {
    recommendations.push(
      'Sesiones muy breves (< 25 min): Indicio de frustración o falta de objetivos claros. Recomendar cadenas de misiones épicas.'
    );
  }

  if (recommendations.length === 0) {
    recommendations.push(
      'Jugador altamente fidelizado: Métricas estables y bajo riesgo. Mantener en ciclo normal de contenido endgame.'
    );
  }

  return {
    retainedProbability,
    churnProbability,
    riskLevel,
    riskColor,
    recommendations
  };
}
